      out.write("\r\n");
      out.write("<script>\r\n");
      out.write("  var WISH_KEY = 'alughadi_wishlist';\r\n");
      out.write("  var CART_KEY = 'alughadi_cart';\r\n");
      out.write("  var _currentFilter = 'all';\r\n");
      out.write("\r\n");
      out.write("  function getWishlist() {\r\n");
      out.write("    try { return JSON.parse(localStorage.getItem(WISH_KEY) || '[]'); }\r\n");
      out.write("    catch(e) { return []; }\r\n");
      out.write("  }\r\n");
      out.write("  function saveWishlist(arr) { localStorage.setItem(WISH_KEY, JSON.stringify(arr)); }\r\n");
      out.write("\r\n");
      out.write("  function getCart() {\r\n");
      out.write("    try { return JSON.parse(localStorage.getItem(CART_KEY) || '[]'); }\r\n");
      out.write("    catch(e) { return []; }\r\n");
      out.write("  }\r\n");
      out.write("  function saveCart(arr) { localStorage.setItem(CART_KEY, JSON.stringify(arr)); }\r\n");
      out.write("\r\n");
      out.write("  /* Sync heart buttons on load */\r\n");
      out.write("  function syncHearts() {\r\n");
      out.write("    var wish = getWishlist();\r\n");
      out.write("    document.querySelectorAll('.product-card').forEach(function(card) {\r\n");
      out.write("      var id   = card.getAttribute('data-id');\r\n");
      out.write("      var btn  = card.querySelector('.prod-save');\r\n");
      out.write("      var tip  = btn ? btn.querySelector('.wish-tip') : null;\r\n");
      out.write("      if (!btn) return;\r\n");
      out.write("      if (wish.indexOf(id) !== -1) {\r\n");
      out.write("        btn.classList.add('saved');\r\n");
      out.write("        btn.querySelector('.wish-heart').innerHTML = '&#9829;'; /* filled ♥ */\r\n");
      out.write("        if (tip) tip.textContent = 'Saved!';\r\n");
      out.write("      } else {\r\n");
