      out.write("    }\r\n");
      out.write("  }\r\n");
      out.write("\r\n");
      out.write("  function toggleWishlist(btn) {\r\n");
      out.write("    var card = btn.closest('.product-card');\r\n");
      out.write("    var id   = card.getAttribute('data-id');\r\n");
      out.write("    var wish = getWishlist();\r\n");
      out.write("    var idx  = wish.indexOf(id);\r\n");
      out.write("    var heart = btn.querySelector('.wish-heart');\r\n");
      out.write("    var tip   = btn.querySelector('.wish-tip');\r\n");
      out.write("\r\n");
      out.write("    if (idx === -1) {\r\n");
      out.write("      wish.push(id);\r\n");
      out.write("      btn.classList.add('saved');\r\n");
      out.write("      heart.innerHTML  = '&#9829;';   /* ♥ filled */\r\n");
      out.write("      if (tip) tip.textContent = 'Saved!';\r\n");
