      out.write("      wish.splice(idx, 1);\r\n");
      out.write("      btn.classList.remove('saved');\r\n");
      out.write("      heart.innerHTML  = '&#9825;';   /* ♡ outline */\r\n");
      out.write("      if (tip) tip.textContent = 'Wishlist';\r\n");
      out.write("      if (typeof showToast === 'function') showToast('Removed from Wishlist', '', '\\u2661');\r\n");
