      out.write("    tabBtn.classList.add('active');\r\n");
      out.write("    var cards = document.querySelectorAll('.product-card');\r\n");
      out.write("    var empty = document.getElementById('fav-empty');\r\n");
      out.write("    if (cat === 'wishlist') {\r\n");
      out.write("      var wish = getWishlist();\r\n");
      out.write("      var shown = 0;\r\n");
      out.write("      cards.forEach(function(card) {\r\n");
      out.write("        var id = card.getAttribute('data-id');\r\n");
      out.write("        if (wish.indexOf(id) !== -1) { card.style.display = ''; shown++; }\r\n");
      out.write("        else { card.style.display = 'none'; }\r\n");
      out.write("      });\r\n");
      out.write("      empty.style.display = shown === 0 ? 'block' : 'none';\r\n");
      out.write("    } else {\r\n");
      out.write("      empty.style.display = 'none';\r\n");
      out.write("      cards.forEach(function(card) {\r\n");
      out.write("        var cc = card.getAttribute('data-cat');\r\n");
      out.write("        card.style.display = (cat === 'all' || cc === cat) ? '' : 'none';\r\n");
      out.write("      });\r\n");
      out.write("    }\r\n");
      out.write("  }\r\n");
